/**
 * AudioSynth.js
 * Procedural Web Audio API synthesizer & multi-voice Chiptune Soundtrack Sequencer
 * for Retro Arcade Studio.
 * Zero external audio assets — all SFX, sirens, marching beats, and 29 distinct
 * game + lobby chiptune soundtracks are synthesized in real-time using OscillatorNodes,
 * GainNodes, and BiquadFilterNodes with sample-accurate Web Audio lookahead scheduling.
 */

const SEMI_MAP = {
  C: 0,
  'C#': 1,
  Db: 1,
  D: 2,
  'D#': 3,
  Eb: 3,
  E: 4,
  F: 5,
  'F#': 6,
  Gb: 6,
  G: 7,
  'G#': 8,
  Ab: 8,
  A: 9,
  'A#': 10,
  Bb: 10,
  B: 11
};

function noteToFreq(note) {
  if (!note || note === '-' || note === 'R') return 0;
  if (typeof note === 'number') return note;
  const m = /^([A-G][b#]?)(-?\d)$/.exec(String(note).trim());
  if (!m) return 0;
  const semi = SEMI_MAP[m[1]];
  if (semi === undefined) return 0;
  const oct = parseInt(m[2], 10);
  const midi = (oct + 1) * 12 + semi;
  return 440 * Math.pow(2, (midi - 69) / 12);
}

